:root {
  --bg: #fafafa;
  --panel-bg: #ffffff;
  --border: #e3e6eb;
  --text: #1f2330;
  --muted: #6b7280;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --highlight: #fde68a;
  --selected: #bfdbfe;
  --shadow: 0 1px 2px rgba(15, 23, 42, 0.05),
            0 4px 12px rgba(15, 23, 42, 0.05);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
               "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
}

.app-header {
  padding: 24px 32px 8px;
  text-align: center;
}

.app-header h1 {
  margin: 0 0 8px;
  font-size: 1.6rem;
  font-weight: 600;
}

.subtitle {
  margin: 0 auto;
  max-width: 720px;
  color: var(--muted);
  font-size: 0.95rem;
  line-height: 1.45;
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(360px, 1fr);
  gap: 24px;
  padding: 16px 32px 40px;
}

.chart-panel,
.table-panel {
  background: var(--panel-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow);
  padding: 20px;
}

.chart-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 18px;
  padding: 4px 4px 12px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  color: var(--text);
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid rgba(0, 0, 0, 0.1);
}

.chart {
  width: 100%;
  min-height: 560px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.chart svg {
  width: 100%;
  height: auto;
  display: block;
}

.bubble {
  cursor: pointer;
  stroke: rgba(255, 255, 255, 0.9);
  stroke-width: 1.5;
  transition: stroke-width 0.15s ease, opacity 0.15s ease;
}

.bubble.selected {
  stroke: #111827;
  stroke-width: 3;
}

.bubble.dimmed {
  opacity: 0.25;
}

.bubble-label {
  pointer-events: none;
  font-family: inherit;
  font-weight: 600;
  fill: #ffffff;
  text-anchor: middle;
  dominant-baseline: central;
  font-size: 11px;
  paint-order: stroke;
  stroke: rgba(0, 0, 0, 0.45);
  stroke-width: 2px;
  stroke-linejoin: round;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(17, 24, 39, 0.92);
  color: #f9fafb;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.85rem;
  line-height: 1.35;
  opacity: 0;
  transform: translate(-50%, -100%);
  transition: opacity 0.15s ease;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);
  z-index: 30;
  max-width: 260px;
}

.tooltip.visible {
  opacity: 1;
}

.tooltip strong {
  font-size: 0.95rem;
  display: block;
  margin-bottom: 2px;
}

.panel-title {
  margin: 0 0 12px;
  font-size: 1.1rem;
  font-weight: 600;
}

.table-scroll {
  max-height: 560px;
  overflow-y: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
}

#data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.92rem;
}

#data-table thead th {
  position: sticky;
  top: 0;
  background: #f3f4f6;
  text-align: left;
  padding: 10px 12px;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

#data-table thead th.num {
  text-align: right;
}

#data-table thead th.sorted-asc::after {
  content: " ▲";
  font-size: 0.7rem;
  color: var(--accent);
}

#data-table thead th.sorted-desc::after {
  content: " ▼";
  font-size: 0.7rem;
  color: var(--accent);
}

#data-table tbody td {
  padding: 8px 12px;
  border-bottom: 1px solid #eef0f3;
  white-space: nowrap;
}

#data-table tbody td.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

#data-table tbody tr {
  cursor: pointer;
}

#data-table tbody tr:hover {
  background: #f8fafc;
}

#data-table tbody tr.selected {
  background: var(--selected);
  font-weight: 600;
}

#data-table tbody tr.selected td:first-child {
  box-shadow: inset 3px 0 0 var(--accent);
}

.empty-cell {
  color: var(--muted);
  font-style: italic;
}

@media (max-width: 960px) {
  .layout {
    grid-template-columns: 1fr;
    padding: 16px;
  }
  .chart {
    min-height: 420px;
  }
}

